/**
 * /study/bible/guides/whole-story-2027   Read the whole story in 2027
 *
 * The Study Bible's story path (every chapter once, in the order the story
 * happened) cut into 365 days of about the same length, generated by
 * scripts/build-story-plan.mjs (lib/storyPlan). The page opens on one day:
 * the one in the address (?day=40), else the reader's place on this device,
 * else today's day in 2027, else day 1. Each day lists its chapters (each
 * opens in the Study Bible on the story path), the context guide that
 * belongs to it, and a plain "Mark day read". Below, the year by month.
 *
 * Position, never performance: the page says which day the reader is on and
 * which day the calendar is on, and never how far behind anyone is. A daily
 * reminder goes into the reader's own calendar (RemindMe), starting January 1.
 */
import { useEffect, useRef, useState } from "react";
import { Link, useLocation, useSearch } from "wouter";
import { ArrowLeft, ArrowRight, Check } from "lucide-react";

import Layout from "@/components/Layout";
import { SEOMeta } from "@/components/SEOMeta";
import { LoadFailed } from "@/components/LoadFailed";
import { RemindMe } from "@/components/RemindMe";
import { SAVE_FAILED } from "@/components/TakeItWithYou";
import { PageHead } from "@/components/editorial/PageHead";
import { Position } from "@/components/study/Position";
import { chapterHref } from "@/lib/bible";
import {
  PLAN_DAYS,
  PLAN_PATH,
  chapterName,
  chaptersOf,
  dayFromQuery,
  dateForDay,
  fetchStoryPlan,
  longDate,
  openingDay,
  planDayFor,
  planMonths,
  readPlanDays,
  readerPlace,
  setPlanDay,
  shortDate,
  type StoryPlan,
} from "@/lib/storyPlan";
import { Status, useLoad } from "@/pages/study-bible/shared";

export default function StudyBibleYear() {
  const { data, retry } = useLoad("story-plan", fetchStoryPlan);
  return (
    <Layout>
      <SEOMeta
        title="Read the Whole Story of the Bible in 2027"
        description="A daily Bible reading plan for 2027: all 1,189 chapters in a year, in the order the story happened, with each day's chapters, a guide to their world where one belongs, your place kept on this device, and a reminder in your calendar."
        url="https://www.livewellbyjamesbell.co/study/bible/guides/whole-story-2027"
      />
      <PageHead
        eyebrow={
          <Link href="/study/bible" style={{ color: "inherit" }}>
            The Study Bible
          </Link>
        }
        title="Read the whole story in 2027"
        lede="Every chapter of the Bible in a year, in the order the story happened. Ten to fifteen minutes a day."
        width="var(--w-prose)"
      />
      {data === null ? (
        <div style={{ padding: "var(--s-6) var(--s-4)" }}>
          <LoadFailed
            what="The reading plan"
            onRetry={retry}
            backHref="/study/bible/story"
            backLabel="The story of the Bible"
          />
        </div>
      ) : data === undefined ? (
        <Status>Opening the plan…</Status>
      ) : (
        <Plan plan={data} />
      )}
    </Layout>
  );
}

function Plan({ plan }: { plan: StoryPlan }) {
  const search = useSearch();
  const [, navigate] = useLocation();
  const [done, setDone] = useState(() => readPlanDays());
  const [today] = useState(() => planDayFor(new Date()));
  const [saveFailed, setSaveFailed] = useState(false);
  // Without a day in the address, the page opens on the reader's place and stays
  // on that day while they mark it read, rather than jumping ahead under their thumb.
  const [opened] = useState(() => openingDay(null, done, today));
  const day = dayFromQuery(search) ?? opened;
  const headingRef = useRef<HTMLHeadingElement>(null);
  const cardRef = useRef<HTMLDivElement>(null);
  const moved = useRef(false);

  // When the reader picks a day below, bring its card into view and start a screen reader there.
  useEffect(() => {
    if (!moved.current) return;
    moved.current = false;
    cardRef.current?.scrollIntoView({ block: "start" });
    headingRef.current?.focus({ preventScroll: true });
  }, [day]);

  const go = (to: number, fromList = false) => {
    if (to < 1 || to > PLAN_DAYS) return;
    moved.current = fromList;
    navigate(`${PLAN_PATH}?day=${to}`, { replace: true });
  };
  const mark = (n: number, read: boolean) => {
    if (!setPlanDay(n, read)) setSaveFailed(true);
    setDone(readPlanDays());
  };

  const d = plan.days[day - 1];
  const act = plan.acts.find(a => a.id === d.act);
  const actBegins = act?.day === day;
  const guides = d.guides
    .map(slug => plan.guides.find(g => g.slug === slug))
    .filter((g): g is { slug: string; title: string } => !!g);
  const place = readerPlace(done);
  const read = done.has(day);
  const inYear = today >= 1 && today <= PLAN_DAYS;
  const reminder =
    today < 1
      ? {
          start: dateForDay(1),
          count: PLAN_DAYS,
          schedule: "every day of 2027, starting January 1",
        }
      : inYear
        ? {
            start: undefined,
            count: PLAN_DAYS - today,
            schedule: "every day through December 31",
          }
        : {
            start: undefined,
            count: PLAN_DAYS,
            schedule: "every day for a year",
          };

  return (
    <>
      <section className="sy-band sy-band--warm" aria-label={`Day ${day}`}>
        <div ref={cardRef} className="sy-day">
          <p className="sy-day__when">
            <Position current={day} total={PLAN_DAYS} unit="Day" /> ·{" "}
            {longDate(day)}
          </p>
          <h2 ref={headingRef} tabIndex={-1} className="sy-day__title">
            {d.label}
          </h2>
          {act &&
            (actBegins ? (
              <p className="sy-day__act">
                {act.act} begins here:{" "}
                <Link href={`/study/bible/story/${act.id}`} className="sy-link">
                  {act.title}
                </Link>
                . Read what happens and the world behind it first.
              </p>
            ) : (
              <p className="sy-day__act">
                <Link href={`/study/bible/story/${act.id}`} className="sy-link">
                  {act.act}: {act.title}
                </Link>
              </p>
            ))}
          <ol className="sy-chapters">
            {chaptersOf(d).map(c => (
              <li key={`${c.slug}/${c.chapter}`}>
                <Link
                  href={`${chapterHref(c.slug, c.chapter)}?path=story`}
                  className="sy-chapter"
                >
                  <span className="sy-chapter__ref">
                    {chapterName(plan.books, c.slug, c.chapter)}
                  </span>
                  {c.title && (
                    <span className="sy-chapter__title">{c.title}</span>
                  )}
                </Link>
              </li>
            ))}
          </ol>
          {guides.length > 0 && (
            <div className="sy-guides">
              <p className="sy-label">In its world</p>
              <ul>
                {guides.map(g => (
                  <li key={g.slug}>
                    <Link
                      href={`/resources/context/${g.slug}`}
                      className="sy-link"
                    >
                      {g.title}
                    </Link>
                  </li>
                ))}
              </ul>
            </div>
          )}
          <div className="sy-day__actions">
            <button
              type="button"
              className={read ? "st-action st-action--quiet" : "st-action"}
              onClick={() => mark(day, !read)}
            >
              {read ? (
                <>
                  <Check size={16} aria-hidden style={{ marginRight: "8px" }} />
                  Day {day} read
                </>
              ) : (
                `Mark day ${day} read`
              )}
            </button>
          </div>
          {saveFailed && (
            <p role="alert" className="sy-note sy-note--alert">
              {SAVE_FAILED}
            </p>
          )}
          <nav aria-label="Days" className="sy-step">
            {day > 1 ? (
              <button
                type="button"
                className="sy-step__btn"
                onClick={() => go(day - 1)}
              >
                <ArrowLeft size={16} aria-hidden /> Day {day - 1}
              </button>
            ) : (
              <span />
            )}
            {day < PLAN_DAYS && (
              <button
                type="button"
                className="sy-step__btn"
                onClick={() => go(day + 1)}
              >
                Day {day + 1} <ArrowRight size={16} aria-hidden />
              </button>
            )}
          </nav>
          <div className="sy-places">
            {today < 1 && (
              <p className="sy-note">
                The plan begins Friday, January 1, 2027. Start early if you
                like: the days are numbered, so your place is kept whatever the
                date.
              </p>
            )}
            {place !== null && done.size > 0 && place !== day && (
              <p className="sy-note">
                Your place on this device:{" "}
                <button
                  type="button"
                  className="sy-inline"
                  onClick={() => go(place)}
                >
                  day {place}
                </button>
                .
              </p>
            )}
            {place === null && (
              <p className="sy-note">
                Every day is marked read on this device: the whole story,
                Genesis to Revelation.
              </p>
            )}
            {inYear && today !== day && (
              <p className="sy-note">
                Today by the calendar:{" "}
                <button
                  type="button"
                  className="sy-inline"
                  onClick={() => go(today)}
                >
                  day {today}
                </button>
                .
              </p>
            )}
            <p className="sy-note">
              Your place is kept on this device. Nothing is sent to LiveWell.
            </p>
          </div>
          {reminder.count > 0 && (
            <RemindMe
              title="Read the whole story: today's chapters"
              details="Today's reading in the whole story of the Bible. The page opens at your place."
              href={PLAN_PATH}
              freq="DAILY"
              count={reminder.count}
              start={reminder.start}
              schedule={reminder.schedule}
              defaultTime="morning"
            />
          )}
        </div>
      </section>

      <Year
        plan={plan}
        day={day}
        done={done}
        onPick={n => go(n, true)}
        onMark={mark}
      />

      <section className="sy-band sy-band--warm">
        <div className="sy-prose">
          <h2 className="sy-h2">How the days are made</h2>
          <p>
            The days follow the Study Bible's{" "}
            <Link href="/study/bible/story" className="sy-link">
              story of the Bible
            </Link>
            , which reads every chapter once in the order the events happened: a
            prophet in the reign he names, a psalm beside the event its heading
            recalls, a letter during Paul's travels. Each of the eleven acts
            begins on a day of its own.
          </p>
          <p>
            Each day is about the same length, close to two thousand words, so a
            day of short psalms and a day of Psalm 119 take about as long. Every
            chapter opens with its study notes. Miss a week and nothing is lost:
            pick up at your place, or at today's day, and read on.
          </p>
        </div>
      </section>
    </>
  );
}

function Year({
  plan,
  day,
  done,
  onPick,
  onMark,
}: {
  plan: StoryPlan;
  day: number;
  done: Set<number>;
  onPick: (n: number) => void;
  onMark: (n: number, read: boolean) => void;
}) {
  const first = (n: number) => {
    const [slug, from] = plan.days[n - 1].read[0];
    return chapterName(plan.books, slug, from);
  };
  const last = (n: number) => {
    const runs = plan.days[n - 1].read;
    const [slug, , to] = runs[runs.length - 1];
    return chapterName(plan.books, slug, to);
  };
  // Only an open month renders its days, so the page holds a month of rows, not a year of them.
  const months = planMonths();
  const monthOf = (n: number) =>
    months.find(m => n >= m.first && n <= m.last)?.name ?? "";
  const [open, setOpen] = useState(() => new Set([monthOf(day)]));
  // When the day changes (a step, a pick, today's day), open its month so its
  // row shows; the reader can still close any month, this one included.
  const [shownDay, setShownDay] = useState(day);
  if (shownDay !== day) {
    setShownDay(day);
    const current = monthOf(day);
    if (!open.has(current)) setOpen(new Set(open).add(current));
  }
  const toggle = (name: string, isOpen: boolean) => {
    if (open.has(name) === isOpen) return;
    const next = new Set(open);
    if (isOpen) next.add(name);
    else next.delete(name);
    setOpen(next);
  };
  return (
    <section className="sy-band" aria-labelledby="sy-year">
      <div className="sy-wrap">
        <h2 id="sy-year" className="sy-h2">
          The year, day by day
        </h2>
        <p className="sy-intro">
          Open a month, then a day. Check off the days you have read.
        </p>
        {months.map(m => (
          <details
            key={m.name}
            className="sy-month"
            open={open.has(m.name)}
            onToggle={e => toggle(m.name, e.currentTarget.open)}
          >
            <summary>
              <span className="sy-month__name">{m.name}</span>
              <span className="sy-month__span">
                {first(m.first)} to {last(m.last)}
              </span>
            </summary>
            {open.has(m.name) && (
              <ol className="sy-days">
                {Array.from(
                  { length: m.last - m.first + 1 },
                  (_, k) => m.first + k
                ).map(n => {
                  const isRead = done.has(n);
                  return (
                    <li
                      key={n}
                      className={n === day ? "sy-row sy-row--on" : "sy-row"}
                    >
                      <button
                        type="button"
                        className="sy-check"
                        aria-pressed={isRead}
                        aria-label={`Day ${n} read`}
                        onClick={() => onMark(n, !isRead)}
                      >
                        {isRead && <Check size={16} aria-hidden />}
                      </button>
                      <button
                        type="button"
                        className="sy-pick"
                        aria-current={n === day ? "true" : undefined}
                        onClick={() => onPick(n)}
                      >
                        <span className="sy-pick__day">
                          Day {n} · {shortDate(n)}
                        </span>
                        <span className="sy-pick__label">
                          {plan.days[n - 1].label}
                        </span>
                      </button>
                    </li>
                  );
                })}
              </ol>
            )}
          </details>
        ))}
      </div>
    </section>
  );
}
